  after(() => provider.finalize());

  it('accepts v2 schema with optional risk fields', async () => {
    await provider.addInteraction({
      state: 'partner supports v2 schema',
      uponReceiving: 'a fraud score webhook',
      withRequest: {
        method: 'POST',
        path: '/partners/123/webhook',
        headers: { 'Content-Type': 'application/json' },
        body: {
          transactionId: 'txn_abc123',
          riskScore: 85,
          newField: 'feature-flag-value', // v2-only field
